// Conecta al BFF (Backend for Frontend) en puerto 8080
// que orquesta los microservicios: proyectos (8081), recursos (8082), analítica (8083)

const API_BASE = 'http://localhost:8080/api/bff/dashboard';

let apiStatusCallback = null;

export function setApiStatusCallback(cb) {
  apiStatusCallback = cb;
}

async function apiFetch(path, opts = {}) {
  try {
    const res = await fetch(API_BASE + path, {
      ...opts,
      headers: {
        'Content-Type': 'application/json',
        ...opts.headers,
      },
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    if (apiStatusCallback) apiStatusCallback(true);
    if (opts.method === 'DELETE') return null;
    const txt = await res.text();
    return txt ? JSON.parse(txt) : null;
  } catch (e) {
    if (apiStatusCallback) apiStatusCallback(false);
    throw e;
  }
}

// ── DASHBOARD ──
export const getDashboard = () => apiFetch('/dashboard');

// ── PROYECTOS ──
export const getProyectos = () => apiFetch('/proyectos');
export const getProyecto = (id) => apiFetch(`/proyectos/${id}`);
export const createProyecto = (data) =>
  apiFetch('/proyectos', { method: 'POST', body: JSON.stringify(data) });
export const updateProyecto = (id, data) =>
  apiFetch(`/proyectos/${id}`, { method: 'PUT', body: JSON.stringify(data) });
export const deleteProyecto = (id) =>
  apiFetch(`/proyectos/${id}`, { method: 'DELETE' });

// ── CLIENTES ──
export const getClientes = () => apiFetch('/clientes');
export const getCliente = (id) => apiFetch(`/clientes/${id}`);
export const createCliente = (data) =>
  apiFetch('/clientes', { method: 'POST', body: JSON.stringify(data) });
export const updateCliente = (id, data) =>
  apiFetch(`/clientes/${id}`, { method: 'PUT', body: JSON.stringify(data) });
export const deleteCliente = (id) =>
  apiFetch(`/clientes/${id}`, { method: 'DELETE' });

// ── RECURSOS ──
export const getRecursos = () => apiFetch('/recursos');
export const getRecurso = (id) => apiFetch(`/recursos/${id}`);
export const createRecurso = (data) =>
  apiFetch('/recursos', { method: 'POST', body: JSON.stringify(data) });
export const updateRecurso = (id, data) =>
  apiFetch(`/recursos/${id}`, { method: 'PUT', body: JSON.stringify(data) });
export const deleteRecurso = (id) =>
  apiFetch(`/recursos/${id}`, { method: 'DELETE' });

// ── ANALÍTICA ──
export const getKpis = () => apiFetch('/analytics/kpis');
export const getReportes = () => apiFetch('/analytics/reportes');
